// Lista real de id_eap, consultada ao vivo no Supabase em 2026-09-18
// (`SELECT DISTINCT id_eap, id_obra FROM EAP`, paginado -- 7093 linhas,
// 15 grupos). NÃO é 1 por obra: obra 107 (NN-AP) tem 6 grupos, obra 94
// (Porto Itapoá) tem 2. `id_eap=66` (obra 103, CNPEM-Auditório) fica de
// fora de propósito -- mesma exclusão já usada em RMI/Mapa de Compras/OC
// (obra 103 não está no array OBRAS do painel). Reconsultar o Supabase se
// uma obra nova ganhar um id_eap que não está aqui.
const ID_EAP = [
  { id_eap: 32,  id_obra: 94,  nome_obra: 'Porto Itapoá' },
  { id_eap: 121, id_obra: 94,  nome_obra: 'Porto Itapoá' },
  { id_eap: 51,  id_obra: 91,  nome_obra: 'Novo Nordisk - UB/SP' },
  { id_eap: 73,  id_obra: 106, nome_obra: 'CNPEM - Faseado' },
  { id_eap: 86,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 87,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 88,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 89,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 90,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 94,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 110, id_obra: 108, nome_obra: 'Novo Nordisk - AP - Reforço' },
  { id_eap: 114, id_obra: 110, nome_obra: 'Hitachi' },
  { id_eap: 115, id_obra: 110, nome_obra: 'Hitachi' },
  { id_eap: 127, id_obra: 114, nome_obra: 'IPEN' },
  // { id_eap: 66, id_obra: 103, nome_obra: 'CNPEM - Auditório' }, -- fora do painel
];

return ID_EAP.map(o => ({ json: o }));

// TODO: mapeamento de campos AINDA NÃO CONFIRMADO -- escrito às cegas,
// sem ter visto uma resposta real do endpoint 'tarefas/{id_eap}'.
// Ajustar os nomes à ESQUERDA (fonte.<campo>) assim que tivermos uma
// amostra real; os nomes à DIREITA já são as colunas reais de
// `eap_tarefas`/`eap_cards_ativos` no MySQL (migration 008_eap.sql).
//
// Node anterior está em Response Format = Text -- o texto cru chega aqui
// em $json.data. Parse manual: se falhar, joga o texto cru (até 1000
// chars) no erro pra dar pra ler na execução do n8n e diagnosticar.
const idEap = $('Loop id_eap (1 por vez)').item.json.id_eap;
const idObra = $('Loop id_eap (1 por vez)').item.json.id_obra;
const nomeObra = $('Loop id_eap (1 por vez)').item.json.nome_obra;

const bruto = typeof $json === 'string' ? $json : ($json.data ?? $json.body ?? JSON.stringify($json));
let corpo;
try {
  corpo = JSON.parse(bruto);
} catch (e) {
  throw new Error(`id_eap ${idEap}: resposta de tarefas nao e JSON valido. Texto cru (ate 1000 chars): ` + String(bruto).slice(0, 1000));
}

const itens = Array.isArray(corpo?.data) ? corpo.data
            : Array.isArray(corpo) ? corpo
            : (() => { throw new Error(`id_eap ${idEap}: envelope inesperado de tarefas: ` + JSON.stringify(corpo).slice(0, 300)); })();

if (typeof corpo?.total === 'number' && corpo.total !== itens.length) {
  throw new Error(`id_eap ${idEap}: API reportou total=${corpo.total} mas vieram ${itens.length} itens -- paginação não confirmada`);
}

const linhasEAP = itens.map(t => ({
  id: Number(t.id),
  id_obra: idObra,
  nome_obra: t.nome_obra || nomeObra,
  id_eap_grupo: idEap,
  edt: t.edt,
  tarefa: t.tarefa,
  disciplina: t.disciplina,
  local: t.local,
  unidade: t.unidade,
  qtd: t.qtd,
  saldo_qtd: t.saldo_qtd,
  efetivo_previsto: t.efetivo_previsto,
  ponderacao_reais: t.ponderacao_reais,
  ponderacao_hht: t.ponderacao_hht,
  data_inicio: t.data_inicio,
  data_termino: t.data_termino,
  data_inicio_reprogramado: t.data_inicio_reprogramado,
  data_termino_reprogramado: t.data_termino_reprogramado,
  encarregado_nome: t.encarregado_nome,
}));

const linhasCards = itens.map(t => ({
  card_id: Number(t.id),
  id_eap_grupo: idEap,
  nome_eap: t.nome_eap,
  id_obra: idObra,
  nome_obra: t.nome_obra || nomeObra,
  edt: t.edt,
  tarefa: t.tarefa,
  resp_planejamento: t.resp_planejamento,
  responsavel_encarregado: t.responsavel_encarregado,
  supervisor_coordenador: t.supervisor_coordenador,
  sincronizado_em: new Date().toISOString(),
}));

return [{ json: { linhasEAP, linhasCards } }];

const escapar = (v) => "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
const valorSql = (v) => {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'NULL';
  return escapar(v);
};

const COLUNAS = [
  'id', 'id_obra', 'nome_obra', 'id_eap_grupo', 'edt', 'tarefa', 'disciplina',
  'local', 'unidade', 'qtd', 'saldo_qtd', 'efetivo_previsto', 'ponderacao_reais',
  'ponderacao_hht', 'data_inicio', 'data_termino', 'data_inicio_reprogramado',
  'data_termino_reprogramado', 'encarregado_nome',
];

const linhas = $json.linhasEAP;
if (!linhas.length) return [{ json: { sql: 'SELECT 1' } }]; // obra sem tarefas nesta rodada

const tuplas = linhas.map(l => '(' + COLUNAS.map(c => valorSql(l[c])).join(',') + ')').join(',\n');
const atualiza = COLUNAS.filter(c => c !== 'id').map(c => `\`${c}\` = VALUES(\`${c}\`)`).join(', ');
const colunasSql = COLUNAS.map(c => `\`${c}\``).join(',');
const sql = `INSERT INTO eap_tarefas (${colunasSql}) VALUES ${tuplas} ON DUPLICATE KEY UPDATE ${atualiza}`;

return [{ json: { sql } }];

const escapar = (v) => "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
const valorSql = (v) => {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'NULL';
  return escapar(v);
};

const COLUNAS = [
  'card_id', 'id_eap_grupo', 'nome_eap', 'id_obra', 'nome_obra', 'edt', 'tarefa',
  'resp_planejamento', 'responsavel_encarregado', 'supervisor_coordenador', 'sincronizado_em',
];

const linhas = $('Montar linhas EAP + cards_ativos (TODO mapear)').item.json.linhasCards;
if (!linhas.length) return [{ json: { sql: 'SELECT 1' } }];

const tuplas = linhas.map(l => '(' + COLUNAS.map(c => valorSql(l[c])).join(',') + ')').join(',\n');
const atualiza = COLUNAS.filter(c => c !== 'card_id').map(c => `\`${c}\` = VALUES(\`${c}\`)`).join(', ');
const colunasSql = COLUNAS.map(c => `\`${c}\``).join(',');
const sql = `INSERT INTO eap_cards_ativos (${colunasSql}) VALUES ${tuplas} ON DUPLICATE KEY UPDATE ${atualiza}`;

return [{ json: { sql } }];
